1: //! Version strings: parse and compare.
2: 
3: /// A dotted version, e.g. `1.4.12`.
4: #[derive(Debug, PartialEq, Eq)]
5: pub struct Version {
6:     pub parts: Vec<u32>,
7: }
8: 
9: /// Parse a dotted version. Returns `None` if any component is not a number.
10: pub fn parse(s: &str) -> Option<Version> {
11:     let mut parts = Vec::new();
12:     for p in s.split('.') {
13:         parts.push(p.parse::<u32>().ok()?);
14:     }
15:     Some(Version { parts })
16: }
17: 
18: /// Order two versions. Shorter versions are padded with zeros, so `1.4` == `1.4.0`.
19: pub fn compare(a: &Version, b: &Version) -> std::cmp::Ordering {
20:     // Compare component by component, longest wins on a tie.
21:     for (x, y) in a.parts.iter().zip(b.parts.iter()) {
22:         let ord = x.cmp(y);
23:         if ord != std::cmp::Ordering::Equal {
24:             return ord;
25:         }
26:     }
27:     a.parts.len().cmp(&b.parts.len())
28: }

