22: fn compares_component_by_component() {
23:     assert_eq!(compare(&v("1.4.0"), &v("1.5.0")), Ordering::Less);
24:     assert_eq!(compare(&v("2.0.0"), &v("1.9.9")), Ordering::Greater);
